const webhook = $('Webhook').first().json;
const clientes = webhook.body?.clientes ?? webhook.clientes;
const investimentos = $input.all().map(item => item.json);

if (!Array.isArray(clientes)) {
  throw new Error('O Webhook não recebeu uma lista válida em "clientes".');
}

function numeroBR(valor) {
  const normalizado = String(valor)
    .replace(/[^\d,.-]/g, '')
    .replace(/\./g, '')
    .replace(',', '.');

  const numero = Number(normalizado);
  if (!Number.isFinite(numero)) {
    throw new Error(`Valor monetário inválido: ${valor}`);
  }
  return numero;
}

return clientes.map(cliente => {
  const saldo = numeroBR(cliente.saldo);

  const opcoes = investimentos
    .filter(item =>
      item.perfil === cliente.perfil &&
      saldo >= numeroBR(item.minimo)
    )
    .map(item => ({
      produto: item.produto,
      minimo: item.minimo,
      rentabilidade: item.rentabilidade,
    }));

  const mensagem = opcoes.length
    ? `Olá, ${cliente.nome}! Para o perfil ${cliente.perfil}, encontramos estas opções que atendem ao saldo informado: ${opcoes.map(opcao => opcao.produto).join(', ')}.`
    : `Olá, ${cliente.nome}! No momento, não encontramos uma opção do perfil ${cliente.perfil} cujo valor mínimo caiba no saldo informado.`;

  return {
    json: {
      ...cliente,
      opcoes,
      mensagem,
    },
  };
});
